import{SYSTEMS,PACKINGS,BALANCED,NEAR_BALANCED}from'./presets.js';import{loadPreset,loadBalanced,setPacking,setField}from'./state.js';let root,refs={};export function mount(r){root=r;r.innerHTML='<div class="control-row"><label>System<select id="system"></select></label><label>Packing<select id="packing"></select></label></div><div class="control-grid">'+[['m','m'],['V','V [kmol/h]'],['yIn','y_in'],['xIn','x_in'],['Eo','Overall tray efficiency'],['traySpacing','Tray spacing [m]'],['hTop','Top allowance [m]'],['hBot','Bottom allowance [m]']].map(a=>'<label>'+a[1]+'<input id="'+a[0]+'" type="number"></label>').join('')+'</div><div class="button-row"><button id="balanced">Balanced (A = 1)</button><button id="near">Near-balanced</button></div><p id="message" class="control-note" aria-live="polite"></p>';refs.system=root.querySelector('#system');refs.packing=root.querySelector('#packing');Object.values(SYSTEMS).forEach(p=>refs.system.add(new Option(p.name,p.id)));refs.system.add(new Option(BALANCED.name,'balanced'));refs.system.add(new Option(NEAR_BALANCED.name,'near-balanced'));Object.values(PACKINGS).forEach(p=>refs.packing.add(new Option(p.name,p.id)));refs.system.onchange=()=>refs.system.value==='balanced'?loadBalanced():refs.system.value==='near-balanced'?loadBalanced(true):loadPreset(SYSTEMS[refs.system.value]);refs.packing.onchange=()=>setPacking(refs.packing.value);root.querySelector('#balanced').onclick=()=>loadBalanced();root.querySelector('#near').onclick=()=>loadBalanced(true);['m','V','yIn','xIn','Eo','traySpacing','hTop','hBot'].forEach(id=>{refs[id]=root.querySelector('#'+id);refs[id].onchange=()=>{const z=setField(id,Number(refs[id].value));if(z?.ok===false)refs.message.textContent=z.message}});refs.message=root.querySelector('#message');return refs}export function update(s,d){['m','V','yIn','xIn','Eo','traySpacing','hTop','hBot'].forEach(id=>{if(document.activeElement!==refs[id])refs[id].value=s[id]});refs.packing.value=s.packing;refs.system.value=s.presetId;refs.message.textContent=s.presetId==='so2'?'Straight-line model strained here: real SO₂-water equilibrium is curved; values are illustrative.':d.reason}